import base64,hashlib,sys,zlib
SOURCE_TEXT=zlib.decompress(base64.b64decode('')).decode()
assert hashlib.sha256(SOURCE_TEXT.encode()).hexdigest()=="8616a0747d7a8e3b28e5af6da86bfdee5b2bf2f84821989c163136ec09479af4"
import fcntl, json, os, select, stat, tarfile, types
from pathlib import Path, PurePosixPath
module = types.ModuleType('g2_postcheck')
module.__dict__['SOURCE_TEXT'] = SOURCE_TEXT
exec(compile(SOURCE_TEXT, 'frozen_g2_postcheck.py', 'exec'), module.__dict__)
project = Path('/home/nss-marker/yhr/Cry')
run_root = project / 'core-window-20261010-51d37af52b90'
archive_path = project / 'core-window-20261010-51d37af52b90.tar'
assert os.geteuid() == 0 and Path.cwd() == project and project.resolve() == project
module.root_gate(recovering=True)
current_cgroups = module.snapshot()
current_frequency = module.frequency_snapshot()
lock_descriptor = os.open(project / 'partition-admin.lock', os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC)
lock_metadata = os.fstat(lock_descriptor)
assert stat.S_ISREG(lock_metadata.st_mode) and lock_metadata.st_uid == 0
assert stat.S_IMODE(lock_metadata.st_mode) == 0o600
fcntl.flock(lock_descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
try:
    root_store = module.Store(run_root)
    saved_source = root_store.load('source.json')
    assert saved_source['sha256'] == hashlib.sha256(SOURCE_TEXT.encode()).hexdigest()
    assert saved_source['source'] == SOURCE_TEXT and root_store.load('run.json')['success'] is True
    cases = {}
    identities = []
    for case in ('normal', 'parent-loss'):
        store = module.Store(run_root / case)
        terminal = store.load('terminal.json')
        observer = store.load('observer.json')
        worker = store.load('worker-exit.json')
        baseline = store.load('frequency-baseline.json')
        assert current_frequency == baseline
        assert current_cgroups['top_names'] == store.load('baseline.json')['top_names']
        assert terminal['success'] and terminal['restoration_visible'] and terminal['evidence_complete']
        assert observer['success'] and observer['guard_pidfd_exit_observed'] and observer['worker_pidfd_exit_observed']
        assert worker['reaped'] and worker['evidence_complete']
        assert all(worker[key] == terminal['worker'][key] for key in terminal['worker'])
        assert terminal['reason'] == ('release' if case == 'normal' else 'controller_eof')
        assert observer['controller_exit_code'] == (0 if case == 'normal' else -9)
        assert worker['worker_exit_code'] == (0 if case == 'normal' else -9)
        assert worker['measurement_complete'] == (case == 'normal')
        if case == 'parent-loss':
            assert worker['cancel_while_running'] and worker['registered_cancel']
            cancelled = store.load('observer-cancel.json')
            released = store.load('worker-released.json')
            assert cancelled['check_monotonic_seconds'] - released['released_monotonic_seconds'] >= 0.25
        case_identities = {}
        for name in ('controller.json', 'guard.json', 'probe-before-exec.json'):
            identity = store.load(name)
            record = {'pid': identity['pid'], 'start_ticks': identity['start_ticks']}
            try:
                descriptor = os.pidfd_open(identity['pid'])
            except ProcessLookupError:
                record['state'] = 'absent'
            else:
                try:
                    ended = bool(select.select([descriptor], [], [], 0)[0])
                    if ended:
                        record['state'] = 'terminated'
                    else:
                        assert module.start_ticks(identity['pid']) != identity['start_ticks']
                        record['state'] = 'reused_by_other_process'
                finally:
                    os.close(descriptor)
            case_identities[name.removesuffix('.json')] = record
            identities.append(record)
        token = run_root.name.rsplit('-', 1)[1] + '-' + case
        for suffix in ('-probe', '-guard'):
            assert not (Path('/sys/fs/cgroup') / ('a113part-' + token + suffix)).exists()
        data = (store.path / 'worker.stdout.jsonl').read_bytes()
        summary = json.loads(data.splitlines()[-1]) if data else None
        if case == 'normal':
            assert summary['type'] == 'summary' and summary['status'] == 'completed' and summary['valid_final_snapshot']
        cases[case] = {'identities': case_identities, 'reason': terminal['reason'],
                       'controller_exit_code': observer['controller_exit_code'], 'worker_exit_code': worker['worker_exit_code'],
                       'restoration_visible': True, 'guard_pidfd_exit_observed': True,
                       'worker_pidfd_exit_observed': True, 'measurement_complete': worker['measurement_complete'],
                       'cancel_while_running': worker['cancel_while_running'],
                       'registered_cancel': worker['registered_cancel'], 'outputs': worker['outputs'], 'summary': summary}
        os.close(store.descriptor)
    assert len(identities) == 6
    archive_descriptor = os.open(archive_path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    assert Path(os.readlink('/proc/self/fd/' + str(archive_descriptor))) == archive_path
    with os.fdopen(archive_descriptor, 'rb') as source:
        archive_hash = hashlib.file_digest(source, 'sha256').hexdigest()
        source.seek(0)
        with tarfile.open(fileobj=source) as archive:
            members = archive.getmembers()
            assert len(members) < 160 and sum(member.size for member in members) < 600 * 1024 * 1024
            names = set()
            for member in members:
                relative = PurePosixPath(member.name)
                assert member.isfile() and not relative.is_absolute() and '..' not in relative.parts and member.name not in names
                names.add(member.name)
                target = run_root / member.name
                metadata = target.stat(follow_symlinks=False)
                assert stat.S_ISREG(metadata.st_mode) and metadata.st_uid == 0 and target.resolve() == target
                data = archive.extractfile(member).read()
                assert target.read_bytes() == data and metadata.st_size == len(data)
                if target.name == 'worker.bin':
                    assert stat.S_IMODE(metadata.st_mode) == 0o500
                    assert hashlib.sha256(data).hexdigest() == module.WINDOW_WORKER_SHA256
            assert names == {str(path.relative_to(run_root)) for path in run_root.rglob('*') if path.is_file()}
    os.close(root_store.descriptor)
finally:
    fcntl.flock(lock_descriptor, fcntl.LOCK_UN)
    os.close(lock_descriptor)
print(json.dumps({'status': 'postcheck_passed', 'source_sha256': hashlib.sha256(SOURCE_TEXT.encode()).hexdigest(),
                  'run_directory': str(run_root), 'archive': str(archive_path), 'archive_sha256': archive_hash,
                  'original_files_equal_archive': len(members), 'original_processes_checked': len(identities),
                  'root_cpus': current_cgroups['root_effective'], 'isolated': current_cgroups['root_isolated'],
                  'all32_frequency_and_global_equal_baseline': True, 'owned_groups_absent': True,
                  'lock_acquired_and_released': True, 'cases': cases, 'configuration_writes': 0,
                  'hardware_frequency_qualified': False, 'r02_signed_off': False, 'r04_signed_off': False}), flush=True)
